<script setup>import {ref,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,useSession,money,toast} from '../core';import State from '../components/State.vue';import Icon from '../components/Icon.vue';const route=useRoute(),router=useRouter(),session=useSession(),product=ref(null),quantity=ref(1),loading=ref(true),error=ref(''),busy=ref(false);async function load(){loading.value=true;error.value='';try{product.value=await api('/products/'+route.params.id)}catch(e){error.value=e.message}finally{loading.value=false}}async function add(){if(!session.user)return router.push({path:'/login',query:{next:route.fullPath}});busy.value=true;try{await api('/cart/'+product.value.id,'POST',{quantity:quantity.value,selected:true});toast('已加入购物车')}catch(e){toast(e.message,true)}finally{busy.value=false}}onMounted(load);</script><template><section class="shell section"><RouterLink to="/shop" class="breadcrumb">← 返回宠物好物</RouterLink><State :loading="loading" :error="error" @retry="load"/><div v-if="product&&!loading&&!error" class="detail-grid product-detail"><div class="detail-image"><img :src="product.image" :alt="product.name"></div><div class="detail-copy"><p class="eyebrow">{{product.category}}</p><h1>{{product.name}}</h1><p class="price large">¥ {{money(product.price)}}</p><span class="offer-label">满减后再享八折 · 模拟优惠</span><p class="preserve detail-lead">{{product.description}}</p><p class="muted">{{product.stock?'可售库存 '+product.stock+' 件':'暂时缺货'}}</p><label class="quantity-label">购买数量<input type="number" v-model.number="quantity" min="1" :max="product.stock" step="1"></label><div class="row"><button class="btn" :disabled="busy||!product.stock" @click="add"><Icon name="bag"/>加入购物车</button><RouterLink to="/cart" class="btn secondary">查看购物车</RouterLink></div><p class="hint">支付均为课程模拟，不发生真实扣款。商品库存以付款时校验为准。</p></div></div></section></template>
